import {CommonModule} from '@angular/common';
import {Component, inject, OnInit} from '@angular/core';
import {FormArray, FormBuilder, FormGroup, ReactiveFormsModule, Validators} from '@angular/forms';
import {UnidadesMedidaService} from "../../../controllers/unidades-medida.service";
import {UnidadesMedidaModel} from "../../../models/unidades-medida.model";
import {PropuestasService} from "../../../controllers/propuestas.service";
import {Router} from "@angular/router";
import {LocalStorageService} from "../../../services/localStorage/local-storage.service";

@Component( {
    selector   : 'app-propuestas-form',
    imports    : [ReactiveFormsModule, CommonModule],
    templateUrl: './propuestas-form.html',
    standalone : true,
    styleUrl   : './propuestas-form.css'
} )
export class PropuestasFormComponent implements OnInit {
    propuestaForm!: FormGroup;
    allowedExtensions                     = ['.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx', '.pdf', '.jpg', '.jpeg', '.png', '.gif'];
    unidadesMedida: UnidadesMedidaModel[] = [];

    private fb                    = inject( FormBuilder )
    private unidadesMedidaService = inject( UnidadesMedidaService );
    private propuestasServices    = inject( PropuestasService );
    private router                = inject( Router );
    private localStorageService   = inject( LocalStorageService );

    async ngOnInit (): Promise<void> {
        const usuarioLogeado = this.localStorageService.getUser();

        if (!usuarioLogeado) {
            await this.router.navigate(['/auth/login']);
            return;
        }

        this.propuestaForm = this.fb.group( {
            user_id           : [usuarioLogeado.user.id, Validators.required],
            tipo              : ['', Validators.required],
            nombre            : ['', Validators.required],
            descripcion       : ['', [Validators.required, Validators.minLength(8)]],
            tiempo_actual     : ['', Validators.required],
            ta_unidad_id      : [1, Validators.required],
            tiempo_esperado   : [{value: '', disabled: true}, Validators.required],
            te_unidad_id      : [{value: 1, disabled: true}, Validators.required],
            cantidad_actual   : ['', Validators.required],
            cantidad_esperada : ['', Validators.required],
            fecha_cumplimiento: ['', Validators.required],
        }, {
            validators: [
                this.tiempoEsperadoValidator.bind(this),
                this.cantidadValidator.bind(this)
            ]
        } );

        // Habilitar/deshabilitar campos de tiempo esperado según tiempo actual
        this.propuestaForm.get('tiempo_actual')?.valueChanges.subscribe(value => {
            if (value) {
                this.propuestaForm.get('tiempo_esperado')?.enable({emitEvent: false});
                this.propuestaForm.get('te_unidad_id')?.enable({emitEvent: false});
            } else {
                this.propuestaForm.get('tiempo_esperado')?.disable({emitEvent: false});
                this.propuestaForm.get('te_unidad_id')?.disable({emitEvent: false});
            }
        });

        // Forzar revalidación cuando cambia el tiempo esperado o su unidad
        this.propuestaForm.get('tiempo_esperado')?.valueChanges.subscribe(() => {
            this.propuestaForm.updateValueAndValidity({emitEvent: false});
        });

        this.propuestaForm.get('te_unidad_id')?.valueChanges.subscribe(() => {
            this.propuestaForm.updateValueAndValidity({emitEvent: false});
        });

        await this.getUnidadesMedida();
    }

    // Getter para acceder fácilmente a los controles del formulario
    get f() {
        return this.propuestaForm.controls;
    }

    get documentos (): FormArray {
        return this.propuestaForm.get( 'documentos' ) as FormArray;
    }

    onFileSelected ( event: Event ): void {
        const input = event.target as HTMLInputElement;
        if ( input.files ) {
            this.agregarArchivos( input.files );
        }
    }

    agregarArchivos ( files: FileList ): void {
        for ( const file of Array.from( files ) ) {
            const extension = file.name.substring( file.name.lastIndexOf( '.' ) ).toLowerCase();
            if ( this.allowedExtensions.includes( extension ) ) {
                this.documentos.push( this.fb.control( file ) );
            }
            else {
                // Manejar archivo no permitido (opcional)
                console.warn( `Archivo no permitido: ${file.name}` );
            }
        }
    }

    async guardar (): Promise<void> {
        if ( !this.propuestaForm.valid ) {
            return;
        }
        const result = await this.propuestasServices.new( this.propuestaForm.value );
        await this.router.navigate(['/main/externos/propuesta-detalle', result?.id]);
    }

    async getUnidadesMedida () {
        this.unidadesMedida = await this.unidadesMedidaService.all();
    }

    // Helper method to convert time values to hours for comparison
    private convertToHours(value: number, unitId: number): number {
        if (!this.unidadesMedida || this.unidadesMedida.length === 0) {
            return value;
        }

        const unidad = this.unidadesMedida.find(u => u.id === unitId);
        if (!unidad) return value;

        const nombre = unidad.nombre.toLowerCase();

        switch (nombre) {
            case 'horas':
                return value;
            case 'días':
            case 'dias':
                return value * 24;
            case 'semanas':
                return value * 168; // 7 * 24
            case 'meses':
                return value * 720; // 30 * 24 (aproximado)
            case 'años':
            case 'anos':
                return value * 8760; // 365 * 24 (aproximado)
            default:
                return value;
        }
    }

    // Custom validator: tiempo esperado must be less than tiempo actual
    private tiempoEsperadoValidator(form: FormGroup): Record<string, boolean> | null {
        const tiempoActual = form.get('tiempo_actual');
        const taUnidadId = form.get('ta_unidad_id');
        const tiempoEsperado = form.get('tiempo_esperado');
        const teUnidadId = form.get('te_unidad_id');

        if (!tiempoActual || !taUnidadId || !tiempoEsperado || !teUnidadId ||
            this.unidadesMedida.length === 0) {
            return null;
        }

        const actualValue = Number(tiempoActual.value);
        const esperadoValue = Number(tiempoEsperado.value);

        if (!actualValue || !esperadoValue || isNaN(actualValue) || isNaN(esperadoValue)) {
            return null;
        }

        const actualEnHoras = this.convertToHours(actualValue, Number(taUnidadId.value));
        const esperadoEnHoras = this.convertToHours(esperadoValue, Number(teUnidadId.value));

        if (esperadoEnHoras > actualEnHoras) {
            tiempoEsperado.setErrors({ tiempoEsperadoInvalido: true });
            return { tiempoEsperadoInvalido: true };
        }

        if (tiempoEsperado.hasError('tiempoEsperadoInvalido')) {
            const errors = { ...tiempoEsperado.errors };
            delete errors['tiempoEsperadoInvalido'];
            tiempoEsperado.setErrors(Object.keys(errors).length > 0 ? errors : null);
        }

        return null;
    }

    // Custom validator: cantidad actual must be greater than cantidad esperada
    private cantidadValidator(form: FormGroup): Record<string, boolean> | null {
        const cantidadActual = form.get('cantidad_actual');
        const cantidadEsperada = form.get('cantidad_esperada');

        if (!cantidadActual || !cantidadEsperada) {
            return null;
        }

        const actualValue = Number(cantidadActual.value);
        const esperadaValue = Number(cantidadEsperada.value);

        if (!actualValue || !esperadaValue || isNaN(actualValue) || isNaN(esperadaValue)) {
            return null;
        }

        if (actualValue < esperadaValue) {
            cantidadEsperada.setErrors({ cantidadEsperadaInvalida: true });
            return { cantidadEsperadaInvalida: true };
        }

        if (cantidadEsperada.hasError('cantidadEsperadaInvalida')) {
            const errors = { ...cantidadEsperada.errors };
            delete errors['cantidadEsperadaInvalida'];
            cantidadEsperada.setErrors(Object.keys(errors).length > 0 ? errors : null);
        }

        return null;
    }
}
