import { Component, EventEmitter, Output, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormGroup, FormBuilder } from '@angular/forms';

export interface FiltroPropuestas {
  nombre?: string;
  tipo?: string;
  fechaCumplimientoInicio?: string;
  fechaCumplimientoFin?: string;
  fechaCreacionInicio?: string;
  fechaCreacionFin?: string;
}

interface FormValues {
  nombre: string;
  tipo: string;
  fechaCumplimientoInicio: string;
  fechaCumplimientoFin: string;
  fechaCreacionInicio: string;
  fechaCreacionFin: string;
}

@Component({
  selector: 'app-filtro-propuestas-component',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './filtro-propuestas-component.html',
  styleUrl: './filtro-propuestas-component.css'
})
export class FiltroPropuestasComponent implements OnInit {
  @Output() filtrar = new EventEmitter<FiltroPropuestas>();
  @Output() limpiar = new EventEmitter<void>();

  filtroForm: FormGroup;
  tipoTramites = [
    { value: '', label: 'Todos los tipos' },
    { value: 'Tramite', label: 'Trámite' },
    { value: 'Servicio', label: 'Servicio' }
  ];

  private fb = inject(FormBuilder);

  constructor() {
    this.filtroForm = this.fb.group({
      nombre: [''],
      tipo: [''],
      fechaCumplimientoInicio: [''],
      fechaCumplimientoFin: [''],
      fechaCreacionInicio: [''],
      fechaCreacionFin: ['']
    });
  }

  ngOnInit(): void {
    // Escuchar cambios en el formulario y emitir filtros automáticamente
    this.filtroForm.valueChanges.subscribe(values => {
      this.emitirFiltros(values);
    });
  }

  private emitirFiltros(values: FormValues): void {
    const filtros: FiltroPropuestas = {};

    // Solo agregar filtros si tienen valores
    if (values.nombre?.trim()) {
      filtros.nombre = values.nombre.trim();
    }
    if (values.tipo) {
      filtros.tipo = values.tipo;
    }
    if (values.fechaCumplimientoInicio) {
      filtros.fechaCumplimientoInicio = values.fechaCumplimientoInicio;
    }
    if (values.fechaCumplimientoFin) {
      filtros.fechaCumplimientoFin = values.fechaCumplimientoFin;
    }
    if (values.fechaCreacionInicio) {
      filtros.fechaCreacionInicio = values.fechaCreacionInicio;
    }
    if (values.fechaCreacionFin) {
      filtros.fechaCreacionFin = values.fechaCreacionFin;
    }

    this.filtrar.emit(filtros);
  }

  onLimpiarFiltros(): void {
    this.filtroForm.reset({
      nombre: '',
      tipo: '',
      fechaCumplimientoInicio: '',
      fechaCumplimientoFin: '',
      fechaCreacionInicio: '',
      fechaCreacionFin: ''
    });
    this.limpiar.emit();
  }

  // Método para validar que la fecha de fin sea posterior a la de inicio
  validarRangoFechas(campoInicio: string, campoFin: string): boolean {
    const fechaInicio = this.filtroForm.get(campoInicio)?.value;
    const fechaFin = this.filtroForm.get(campoFin)?.value;

    if (fechaInicio && fechaFin) {
      return new Date(fechaInicio) <= new Date(fechaFin);
    }
    return true;
  }
}
