import {Component, inject, OnInit, ViewChild, ElementRef} from '@angular/core';
import {CommonModule, DatePipe} from '@angular/common';
import {ParamMap, Router, RouterLink} from '@angular/router';
import {ActivatedRoute} from '@angular/router';
import {PropuestasModel} from "../../../models/propuestas.model";
import {PropuestasService} from "../../../controllers/propuestas.service";
import {PropuestasDocumentosModel} from "../../../models/propuestas-documentos.model";
import {PropuestasDocumentosService} from "../../../controllers/propuestas-documentos.service";

@Component({
    selector: 'app-propuestas-detalle',
    imports: [
        CommonModule,
        DatePipe,
        RouterLink
    ],
    templateUrl: './propuestas-detalle.html',
    styleUrl: './propuestas-detalle.css'
})
export class PropuestasDetalle implements OnInit {
    propuesta: PropuestasModel | null = null;
    isLoading = true;
    error: string | null = null;

    propuestasDocumentos: PropuestasDocumentosModel[] = [];
    documentosSeleccionados: PropuestasDocumentosModel[] = [];
    @ViewChild('fileInput') fileInput!: ElementRef<HTMLInputElement>;
    private documentoIdCounter = 1;
    propuestaId = 0;

    private route = inject(ActivatedRoute);
    private router = inject(Router);
    private propuestasService = inject(PropuestasService);
    private propuestasDocumentosService = inject(PropuestasDocumentosService);

    ngOnInit(): void {
        this.route.paramMap.subscribe((params: ParamMap) => {
            const idParam = params.get('id');

            if (idParam) {
                const id = parseInt(idParam, 10);
                if (!isNaN(id)) {
                    this.propuestaId = id;
                    void this.cargarPropuesta(id);
                } else {
                    this.error = 'ID de propuesta inválido';
                    this.isLoading = false;
                }
            } else {
                this.error = 'ID de propuesta no proporcionado';
                this.isLoading = false;
            }
        });
    }

    /**
     * Cargar los datos de la propuesta y sus documentos
     * @param id
     */
    async cargarPropuesta(id: number): Promise<void> {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const resultado = await this.propuestasService.find(id, { relations: ['documentos', 'tiempoActualUnidad', 'tiempoEsperadoUnidad'], loader: true } as any);
        this.propuesta = resultado || null;
        if (this.propuesta) {
            const { documentos } = this.propuesta;
            this.propuestasDocumentos = documentos ?? [];
            console.log(this.propuestasDocumentos);
        }

        if (!this.propuesta) {
            this.error = 'Propuesta no encontrada';
        }
    }

    volver(): void {
        void this.router.navigate(['/main/externos/propuesta-list']);
    }

    editarPropuesta(): void {
        if (this.propuesta?.id) {
            void this.router.navigate(['/main/externos/propuesta-editar', this.propuesta.id]);
        }
    }

    //#region Métdos para los Documentos
    triggerFileInput(): void {
        this.fileInput.nativeElement.click();
    }

    async onFileSelected(event: Event): Promise<void> {
        const input = event.target as HTMLInputElement;
        if (input.files && input.files.length > 0) {
            for ( const file of Array.from( input.files ) ) {
                const documento: PropuestasDocumentosModel = {
                    id: this.documentoIdCounter++,
                    propuesta_id: this.propuestaId,
                    nombre: file.name,
                    tamano: file.size,
                    tipo: file.type || this.getFileType(file.name),
                };
                // -- Enviar al backend
                await this.propuestasDocumentosService.saveDocument(documento, file);
                // -- Recarga de los datos
                await this.cargarPropuesta(this.propuestaId);
            }
            input.value = '';
        }
    }

    async eliminarDocumento(id: number): Promise<void> {
       await this.propuestasDocumentosService.switch(id);
       // -- Volver a cargar los datos
       await this.cargarPropuesta(this.propuestaId);
    }

    async mostrarDocumento(id: number): Promise<void> {
        // Construir la URL del documento (asumiendo que tiene una propiedad url_archivo)
        const documentUrl = this.propuestasDocumentosService.getUrlDocsPropuestas(id);

        if (documentUrl) {
            // Abrir el documento en una nueva pestaña
            window.open(documentUrl, '_blank');
        } else {
            console.error('El documento no tiene una URL válida');
            // Aquí podrías mostrar una notificación al usuario
        }
    }

    formatFileSize(bytes: number): string {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }

    getFileType(fileName: string): string {
        const extension = fileName.split('.').pop()?.toLowerCase() || '';
        const typeMap = new Map<string, string>([
            ['pdf', 'PDF'],
            ['doc', 'Word'],
            ['docx', 'Word'],
            ['xls', 'Excel'],
            ['xlsx', 'Excel'],
            ['png', 'Imagen'],
            ['jpg', 'Imagen'],
            ['jpeg', 'Imagen']
        ]);
        return typeMap.get(extension) || 'Archivo';
    }
    //#endregion
}