import {Component, inject, OnInit} from '@angular/core';
import {AbstractControl, FormBuilder, FormGroup, ReactiveFormsModule, Validators} from "@angular/forms";
import {UnidadesAdministrativasService} from "../../../controllers/unidades-administrativas.service";
import {UnidadesAdministrativas} from "../../../models/unidades-administrativas.model";
import {SelectorDireccionesSei} from "../selector-direcciones-sei/selector-direcciones-sei";
import {DireccionesSei} from "../../../models/direcciones-sei.model";
import {LocalStorageService} from "../../../services/localStorage/local-storage.service";
import {DatosInicialesModel} from "../../../models/datos-iniciales.model";
import {DatosInicialesService} from "../../../controllers/datos-iniciales.service";
import {Router} from "@angular/router";

@Component({
    selector: 'app-datos-usuarios',
    imports: [
        ReactiveFormsModule,
        SelectorDireccionesSei
    ],
    templateUrl: './datos-usuarios.html',
    styleUrl: './datos-usuarios.css'
})
export class DatosUsuarios implements OnInit {
    public readonly titulo = "Datos Usuario";
    formDatosIniciales!: FormGroup;
    unidadesAdministrativas: UnidadesAdministrativas[] = [];
    direccionSeiSelecccionado!: DireccionesSei;

    private formBuilder = inject(FormBuilder);
    private unidadAdminService = inject(UnidadesAdministrativasService);
    private datosIniciales = inject( DatosInicialesService);
    private ls = inject(LocalStorageService);
    private router = inject(Router);

    // Acceso al control del formulario
    get f(): Record<string, AbstractControl> {
        return this.formDatosIniciales.controls;
    }

    async ngOnInit(): Promise<void> {
        this.formDatosIniciales = this.formBuilder.group({
            user_id: 0,
            unidad_admin: ['', [Validators.required]],
            oficina_titular: ['', Validators.required],
            nombre_servidor: ['', [Validators.required]],
            email: ['', [Validators.required]],
            telefono: ['', [Validators.required]],
            extension: ['', [Validators.required]],
        });

        await this.getCatalogos();

        const user = this.ls.getUser();
        console.log(user?.user);
        this.formDatosIniciales.patchValue({ user_id: user?.user.id})
    }

    async onSubmit() {
        if(this.formDatosIniciales.invalid) {
            this.formDatosIniciales.markAllAsTouched();
            return;
        }

        const datosInciales: DatosInicialesModel = {
            ...this.formDatosIniciales.value,
        };
        console.log(datosInciales);

        const result = await this.datosIniciales.new(datosInciales)
        if ( result ) {
            this.ls.updateDatosIniciales(result);
            await this.router.navigate(['/main/externos/datos-iniciales-registrados']);
        }
    }

    onDireccionChange(direccion: DireccionesSei) {
        this.formDatosIniciales.patchValue({
            oficina_titular: `${direccion.id}-${direccion.nombre}`,
        })
        // this.direccionSeiSelecccionado = direccion;
        // console.log(this.direccionSeiSelecccionado);

    }

    async getCatalogos() {
        this.unidadesAdministrativas = await this.unidadAdminService.all();
        console.log(this.unidadAdminService);
    }

}
