import {Component, inject, OnInit} from '@angular/core';
import {DatosInicialesService} from "../../../controllers/datos-iniciales.service";
import {LocalStorageService} from "../../../services/localStorage/local-storage.service";
import {DatosInicialesModel} from "../../../models/datos-iniciales.model";

@Component({
    selector: 'app-datos-iniciales-registrados',
    imports: [],
    templateUrl: './datos-iniciales-registrados.html',
    styleUrl: './datos-iniciales-registrados.css'
})
export class DatosInicialesRegistrados implements OnInit {

    public datosIniciales!: DatosInicialesModel;

    private datosInicialesServices = inject(DatosInicialesService);
    private localStorage = inject(LocalStorageService);

    async ngOnInit(): Promise<void> {
        const user = this.localStorage.getUser();
        console.log(user?.user);
        if ( user && user.user.datos_iniciales ) {
            await this.getDatosIniciales(user.user.datos_iniciales.id)
        }
    }

    async getDatosIniciales (id: number) {
        const result = await this.datosInicialesServices.find(id, {relations: ['unidadAdministrativa']});
        if ( result ) {
            this.datosIniciales = { ...result };
        }
    }
}
