import { Component, EventEmitter, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import {DireccionesSei} from "../../../models/direcciones-sei.model";

export interface DireccionNode {
  id: string;
  nombre: string;
  hijos?: DireccionNode[];
}

@Component({
  selector: 'app-selector-direcciones-sei',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './selector-direcciones-sei.html',
  styleUrl: './selector-direcciones-sei.css'
})
export class SelectorDireccionesSei {

  @Output() direccionSeleccionada = new EventEmitter<DireccionesSei>();

  public selectedDireccion: DireccionesSei | null = null;
  public isDropdownOpen = false;

  public direcciones: DireccionesSei[] = [
    {
      id: '1',
      nombre: 'Dirección de Administración',
      hijos: [
        { id: '1.1', nombre: 'Unidad de Ensenada.' },
        { id: '1.2', nombre: 'Dirección de Normatividad' },
        { id: '1.3', nombre: 'Dirección de Economía Binacional' },
      ],
    },
    {
      id: '2',
      nombre: 'Subsecretaría de Planeación Económica',
      hijos: [
        { id: '2.1', nombre: 'Dirección de Estadística' },
        { id: '2.2', nombre: 'Dirección de Proyectos Estratégicos de Inversión Productiva' },
      ],
    },
    {
      id: '3',
      nombre: 'Subsecretaría de Fomento Económico',
      hijos: [
        { id: '3.1', nombre: 'Dirección de Emprendimiento y Desarrollo Empresarial' },
        { id: '3.2', nombre: 'Dirección de Competitividad y Mejora Regulatoria' },
        { id: '3.3', nombre: 'Dirección de Financiamiento' },
        { id: '3.4', nombre: 'Dirección de Sectores y Cadenas Productivas' },
        { id: '3.5', nombre: 'Dirección de Atención Ciudadana' },
      ],
    },
    {
      id: '4',
      nombre: 'Subsecretaría de Gestión de Inversión',
      hijos: [
        { id: '4.1', nombre: 'Dirección de Promoción de la Inversión e Integración Productiva' },
        { id: '4.2', nombre: 'Dirección de Impulso a la Innovación y Tecnología' },
      ],
    },
    {
      id: '5',
      nombre: 'Subsecretaría de Industrias Creativas',
      hijos: [
        {
          id: '5.1',
          nombre: 'Dirección de Fortalecimiento al Sector Creativo',
          hijos: [
            { id: '5.1.1', nombre: 'Departamento de Alianzas Estratégicas del Sector Creativo' },
            { id: '5.1.2', nombre: 'Departamento de Fomento a las Industrias Creativas' },
            { id: '5.1.3', nombre: 'Departamento de Impulso a la Industria Fílmica' },
          ],
        },
      ],
    },
  ];

  public toggleDropdown(): void {
    this.isDropdownOpen = !this.isDropdownOpen;
  }

  public seleccionarDireccion(node: DireccionesSei): void {
    if (!node.hijos || node.hijos.length === 0) {
      this.selectedDireccion = node;
      this.direccionSeleccionada.emit(node);
      this.isDropdownOpen = false;
    }
  }
}