import {Component, Input, AfterViewChecked, ViewChild, ElementRef, inject, OnInit} from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {PropuestaFeedbackService} from "../../../../controllers/propuesta-feedback.service";
import {PropuestaFeedbackModel} from "../../../../models/propuesta-feedback.model";
import {UtilsService} from "../../../../services/utils.service";
import {LocalStorageService} from "../../../../services/localStorage/local-storage.service";

@Component({
  selector: 'app-feed-back',
  imports: [CommonModule, FormsModule, DatePipe],
  templateUrl: './feed-back.html',
  styleUrl: './feed-back.css'
})
export class FeedBack implements AfterViewChecked, OnInit {
  @Input() propuestaId = 0;
  @ViewChild('chatContainer') chatContainer!: ElementRef;

  private feedbackService = inject(PropuestaFeedbackService);
  private utilsService = inject(UtilsService);
  private storage = inject(LocalStorageService);

  feedbackComentarios: PropuestaFeedbackModel[] = [];
  nuevoComentario = '';
  // Usuario logeado obtenido del sistema de autenticación
  get currentUser() {
    const userData = this.storage.getUser();
    return userData?.user || null;
  }

  private shouldScroll = false;

  async ngOnInit(): Promise<void> {
    await this.cargarFeedback();
  }

  async cargarFeedback(): Promise<void> {
    if (this.propuestaId) {
      try {
        const response = await this.feedbackService.get({
          conditionals: [{ key: 'propuesta_id', operator: '=', value: this.propuestaId }],
          relations: ['user']
        });

        if ( response.status && response.data) {
          this.feedbackComentarios = response.data;
          this.shouldScroll = true;
        }
      } catch (error) {
        console.error('Error al cargar feedback:', error);
      }
    }
  }

  async agregarComentario(): Promise<void> {
    if (this.nuevoComentario.trim() && this.propuestaId && this.currentUser) {
      const nuevoFeedback: Partial<PropuestaFeedbackModel> = {
        propuesta_id: this.propuestaId,
        texto: this.nuevoComentario,
        fecha: this.utilsService.toMySQLDateTime(new Date())!,
        user_id: this.currentUser.id,
        es_propietario: true
      };

      try {
        const response = await this.feedbackService.new(nuevoFeedback);
        if (response) {
          // Recargar comentarios para obtener datos actualizados
          await this.cargarFeedback();
          this.nuevoComentario = '';
          this.shouldScroll = true;
        }
      } catch (error) {
        console.error('Error al agregar comentario:', error);
      }
    }
  }

  // Manejo de teclado para enviar mensaje con Enter
  async onKeyPress(event: KeyboardEvent): Promise<void> {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      await this.agregarComentario();
    }
  }

  // Auto-scroll al último mensaje
  ngAfterViewChecked(): void {
    if (this.shouldScroll && this.chatContainer) {
      try {
        this.chatContainer.nativeElement.scrollTop = this.chatContainer.nativeElement.scrollHeight;
      } catch (err) {
        console.error('Error al hacer scroll:', err);
      }
      this.shouldScroll = false;
    }
  }

  // Verificar si hay usuario autenticado
  isAuthenticated(): boolean {
    return this.currentUser !== null;
  }

  // Verificar si el usuario está escribiendo (para futura implementación)
  isTyping(): boolean {
    return this.nuevoComentario.trim().length > 0;
  }
}
