import {Component, inject, OnInit, ViewChild} from '@angular/core';
import {DatePipe, CommonModule} from '@angular/common';
import {FormBuilder, FormGroup, FormsModule, Validators, ReactiveFormsModule, AbstractControl} from '@angular/forms';
import {PropuestasModel} from '../../../models/propuestas.model';
import {PropuestasService} from "../../../controllers/propuestas.service";
import {ActivatedRoute, ParamMap, RouterLink} from "@angular/router";
import {TiposAvancesService} from "../../../controllers/tipos-avances.service";
import {TiposAvancesModel} from "../../../models/tipos-avances.model";
import {PropuestasAvancesService} from "../../../controllers/propuestas-avances.service";
import {PropuestasAvancesModel} from "../../../models/propuestas-avances.model";
import {HistorialAvances} from './historial-avances/historial-avances';
import {FeedBack} from './feed-back/feed-back';
import {EvidenciasDocumentales} from './evidencias-documentales/evidencias-documentales';

@Component( {
    selector   : 'app-registro-avances',
    imports    : [CommonModule, FormsModule, ReactiveFormsModule, DatePipe, RouterLink, HistorialAvances, FeedBack, EvidenciasDocumentales],
    templateUrl: './registro-avances.html',
    styleUrl   : './registro-avances.css'
} )
export class RegistroAvances implements OnInit {
    propuestaId                       = 0;
    propuesta?: PropuestasModel;
    tiposAvances: TiposAvancesModel[] = [];
    avancesForm!: FormGroup;

    // Propiedades para modo dual (crear/editar)
    editMode = false;
    editingAvanceId: number | null = null;
    formTitle = 'Registrar Nuevo Avance';
    submitButtonText = 'Guardar Avance';

  
    // Referencia al componente hijo para comunicación
    @ViewChild( HistorialAvances ) historialComponent!: HistorialAvances;

    private activatedRoute           = inject( ActivatedRoute );
    private propuestasService        = inject( PropuestasService );
    private tiposAvancesService      = inject( TiposAvancesService );
    private propuestasAvancesService = inject( PropuestasAvancesService );
    private fb                       = inject( FormBuilder );

    async ngOnInit (): Promise<void> {
        // -- Formulario de Avances con validaciones mejoradas (incluye ID para edición)
        this.avancesForm = this.fb.group( {
            id: [null], // Campo ID para edición
            propuesta_id   : [this.propuestaId, [Validators.required]],
            avance         : ['', [Validators.required, Validators.minLength( 20 )]],
            fecha_avance   : ['', [Validators.required]],
            porcentaje     : ['', [Validators.required, Validators.min( 0 ), Validators.max( 100 )]],
            tipos_avance_id: ['', [Validators.required]],
        } );

        this.activatedRoute.paramMap.subscribe( async ( params: ParamMap ) => {
            const idParam = params.get( 'id' );
            if ( idParam ) {
                this.propuestaId = parseInt( idParam );
                await this.getPropuesta( this.propuestaId );
            }
        } );
        await this.getCatalogoTiposAvanaces();

        // Actualizar propuesta_id cuando se carga
        if ( this.propuestaId > 0 ) {
            this.avancesForm.patchValue( {propuesta_id: this.propuestaId} );
        }
    }

    
    get f (): Record<string, AbstractControl> {
        return this.avancesForm.controls;
    }

    async onSubmit (): Promise<void> {
        if ( !this.avancesForm.valid ) {
            // Marcar todos los campos como touched para mostrar validaciones
            Object.keys( this.avancesForm.controls ).forEach( key => {
                const control = this.avancesForm.get( key );
                control?.markAsTouched();
            } );
            alert( 'Por favor, complete todos los campos requeridos correctamente.' );
            return;
        }

        const formData = this.avancesForm.value;

        try {
            if ( this.editMode && this.editingAvanceId ) {
                // Modo edición: actualizar avance existente
                const updateResponse = await this.propuestasAvancesService.update( this.editingAvanceId, formData );
                console.log( 'Avance actualizado exitosamente:', updateResponse );
            } else {
                // Modo creación: nuevo avance
                const createResponse = await this.propuestasAvancesService.new( formData );
                console.log( 'Avance guardado exitosamente:', createResponse );
            }

            // ✅ Notificar al componente hijo que recargue los datos
            await this.historialComponent.refreshAvances();

            // Resetear formulario y volver a modo creación
            this.switchToCreateMode();
        } catch ( error ) {
            console.error( 'Error al guardar el avance:', error );
            alert( 'Error al guardar el avance. Por favor, intente nuevamente.' );
        }
    }

    // -- Obtención de la Propuesta y Catálogos
    async getPropuesta ( id: number ): Promise<void> {
        this.propuesta = await this.propuestasService.find( id, {relations: ['documentos'], loader: true} );
        console.log( this.propuesta );
    }

    async getCatalogoTiposAvanaces (): Promise<void> {
        this.tiposAvances = await this.tiposAvancesService.all( {loader: true} );
        console.log( this.tiposAvances );
    }

    // ===== MÉTODOS PARA MODO DUAL (CREAR/EDITAR) =====

    /**
     * Manejar solicitud de edición desde el componente hijo
     */
    onEditRequest ( avance: PropuestasAvancesModel ): void {
        this.switchToEditMode( avance );

        // Auto-scroll al formulario para mejor UX
        setTimeout( () => {
            document.getElementById( 'formulario-avances' )?.scrollIntoView( {
                behavior: 'smooth',
                block: 'center'
            } );
        }, 100 );
    }

    /**
     * Cambiar a modo edición con datos del avance
     */
    private switchToEditMode ( avance: PropuestasAvancesModel ): void {
        this.editMode = true;
        this.editingAvanceId = avance.id;
        this.formTitle = 'Editar Avance';
        this.submitButtonText = 'Actualizar Avance';

        // Cargar datos del avance en el formulario
        this.avancesForm.patchValue( {
            id: avance.id,
            propuesta_id: avance.propuesta_id,
            avance: avance.avance,
            fecha_avance: avance.fecha_avance,
            porcentaje: avance.porcentaje,
            tipos_avance_id: avance.tipos_avance_id
        } );

        // Marcar campos como touched para mostrar validaciones si es necesario
        this.avancesForm.markAllAsTouched();
    }

    /**
     * Cambiar a modo creación (resetear formulario)
     */
    switchToCreateMode (): void {
        this.editMode = false;
        this.editingAvanceId = null;
        this.formTitle = 'Registrar Nuevo Avance';
        this.submitButtonText = 'Guardar Avance';

        // Resetear formulario completamente
        this.avancesForm.reset();

        // Mantener propuesta_id después del reset
        if ( this.propuestaId > 0 ) {
            this.avancesForm.patchValue( { propuesta_id: this.propuestaId } );
        }

        // Marcar campos como untouched para modo creación
        this.avancesForm.markAsUntouched();
    }

    /**
     * Cancelar edición y volver a modo creación
     */
    cancelEdit (): void {
        this.switchToCreateMode();
    }
}
