import {inject} from '@angular/core';
import {CanActivateFn, Router, UrlTree} from '@angular/router';
import {LocalStorageService} from "../services/localStorage/local-storage.service";

export const initialDataGuard: CanActivateFn = (route, state): boolean | UrlTree => {
    const localStorageService = inject(LocalStorageService);
    const router = inject(Router);
    const usuario = localStorageService.getUser();

    if (!usuario) {
        return router.createUrlTree(['/auth/login']);
    }

    const {user} = usuario;
    const targetUrl = state.url;

    const datosUsuarioUrl = '/main/externos/datos-usuario'; // -- Formulario de Alta de los Datos iniciales
    const datosRegistradosUrl = `/main/externos/${route.url.toString()}`;

    if (user.datos_iniciales === null) {
        // Si los datos son nulos, el destino correcto es 'datos-usuario'.
        if (targetUrl.startsWith(datosUsuarioUrl)) {
            return true; // Si ya estamos yendo ahí, permitir.
        }
        return router.createUrlTree([datosUsuarioUrl]); // Si no, redirigir.
    } else {
        // Si los datos existen, el destino es 'datos-iniciales-registrados'.
        if (targetUrl.startsWith(datosRegistradosUrl)) {
            return true; // Si ya estamos yendo ahí, permitir.
        }
        return router.createUrlTree([datosRegistradosUrl]); // Si no, redirigir.
    }
};
