import {Routes} from "@angular/router";
import {DatosUsuarios} from "./datos-usuarios/datos-usuarios";
import {PropuestasList} from "./propuestas-list/propuestas-list";
import {PropuestasFormComponent} from "./propuestas-form/propuestas-form";
import {PropuestasDetalle} from "./propuestas-detalle/propuestas-detalle";
import {initialDataGuard} from "../../guards/initial-data.guard";
import {DatosInicialesRegistrados} from "./datos-iniciales-registrados/datos-iniciales-registrados";
import {RegistroAvances} from "./registro-avances/registro-avances";

export const externosRoutes: Routes = [
    // -- Datos Iniciales
    {path: 'datos-usuario', component: DatosUsuarios, title: 'Datos Usuarios'},
    {path          : 'datos-iniciales-registrados',
        canActivate: [initialDataGuard],
        component  : DatosInicialesRegistrados,
        title      : 'Datos Iniciales'
    },

    // -- Propuestas de Mejora
    {path: 'propuesta', pathMatch: 'full', redirectTo: 'propuesta-list'},
    {path          : 'propuesta-nuevo',
        canActivate: [initialDataGuard],
        component  : PropuestasFormComponent,
        title      : 'Nueva Propuesta'
    },
    {path          : 'propuesta-list',
        canActivate: [initialDataGuard],
        component  : PropuestasList,
        title      : 'Propuestas Genereadas'
    },
    {path: 'propuesta-detalle/:id', component: PropuestasDetalle, title: 'Detalle de Propuesta'},

    // -- Registro de Avances
    {path: 'registro-avances/:id', component: RegistroAvances, title: 'Registro de Avances'},
]