import { Component, Input, OnChanges, SimpleChanges, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { PropuestaEvidenciaModel } from '../../../../models/propuesta-evidencia.model';
import { PropuestaEvidenciaService } from '../../../../controllers/propuesta-evidencia.service';

@Component({
  selector: 'app-evidencias-documentales',
  imports: [CommonModule],
  templateUrl: './evidencias-documentales.html',
  styleUrl: './evidencias-documentales.css'
})
export class EvidenciasDocumentales implements OnChanges {
    @Input() propuestaId = 0;
    @Input() readonly = false;

    documentosEvidencia: PropuestaEvidenciaModel[] = [];

    private propuestaEvidenciaService = inject(PropuestaEvidenciaService);

    /**
     * Detecta cambios en los inputs y carga documentos cuando propuestaId cambia
     */
    async ngOnChanges(changes: SimpleChanges): Promise<void> {
        if (changes['propuestaId']) {
            const nuevoValor = changes['propuestaId'].currentValue;
            if (nuevoValor && nuevoValor > 0) {
                await this.cargarDocumentos();
            }
        }
    }

    /**
     * Carga los documentos de evidencia desde el backend
     */
    async cargarDocumentos(): Promise<void> {
        if (this.propuestaId) {
            try {
                const response = await this.propuestaEvidenciaService.get({
                    conditionals: [{ key: 'propuesta_id', operator: '=', value: this.propuestaId }],
                    loader: true,
                });

                if (response.status && response.data) {
                    this.documentosEvidencia = response.data;
                    console.log(this.documentosEvidencia);
                }
            } catch (error) {
                console.error('Error al cargar documentos:', error);
            }
        }
    }

    /**
     * Maneja la selección de archivos desde el input
     */
    async onFileSelected(event: Event): Promise<void> {
        console.log('Archivos seleccionados:', event);
        const inputElement = event.target as HTMLInputElement;
        if (inputElement.files && inputElement.files.length > 0) {
            for (const file of inputElement.files) {

                // Validar tamaño máximo (10MB)
                if (file.size > 10 * 1024 * 1024) {
                    console.warn(`El archivo ${file.name} excede el tamaño máximo de 10MB`);
                    continue;
                }

                // Crear objeto para guardar en el backend
                const nuevaEvidencia: Partial<PropuestaEvidenciaModel> = {
                    propuesta_id: this.propuestaId,
                    nombre: file.name,
                    tamano: file.size,
                    tipo: file.type
                };

                // Guardar en el backend
                const resultado = await this.propuestaEvidenciaService.saveDocument(
                  nuevaEvidencia as PropuestaEvidenciaModel,
                  file
                );

                if (resultado) {
                    // Agregar a la lista local
                    this.documentosEvidencia.push(resultado);
                }
            }

            // Limpiar el input para permitir seleccionar el mismo archivo nuevamente
            inputElement.value = '';
        }
    }

    /**
     * Formatea el tamaño de un archivo a formato legible
     */
    formatFileSize(bytes: number): string {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }

    /**
     * Ver un documento en una nueva ventana usando URL del backend
     */
    verDocumento(documento: PropuestaEvidenciaModel): void {
        if (documento.id) {
            const urlDescarga = this.propuestaEvidenciaService.getUrlDocsPropuestas(documento.id);
            window.open(urlDescarga, '_blank');
        } else {
            console.warn('No hay ID disponible para el documento:', documento.nombre);
        }
    }

    /**
     * Eliminar un documento (eliminación suave)
     */
    async eliminarDocumento(id: number): Promise<void> {
        const resultado = await this.propuestaEvidenciaService.switch(id);
        if (resultado) {
            // Eliminar de la lista local
            const index = this.documentosEvidencia.findIndex(doc => doc.id === id);
            if (index !== -1) {
                this.documentosEvidencia.splice(index, 1);
            }
        }

    }

    /**
     * Recargar documentos desde el backend (método público)
     */
    async refreshDocuments(): Promise<void> {
        await this.cargarDocumentos();
    }
}
