import {Component, inject, Input, OnChanges, SimpleChanges, Output, EventEmitter} from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { PropuestasAvancesService } from '../../../../controllers/propuestas-avances.service';
import { VanillaDialogService, DialogData } from '../../../../services/vanilla-dialog/vanilla-dialog.service';
import {PropuestasAvancesModel} from "../../../../models/propuestas-avances.model";

@Component({
  selector: 'app-historial-avances',
  imports: [CommonModule, DatePipe],
  templateUrl: './historial-avances.html',
  styleUrl: './historial-avances.css'
})
export class HistorialAvances implements OnChanges {
  // Input y Output para comunicación con el padre
  @Input() propuestaId = 0;
  @Output() editRequest = new EventEmitter<PropuestasAvancesModel>();

  // Estado del componente
  avances: PropuestasAvancesModel[] = [];
  isLoading = false;
  errorMessage = '';

  private propuestasAvancesService = inject(PropuestasAvancesService);
  private dialogService = inject(VanillaDialogService);

  // Recargar cuando cambia el propuestaId
  async ngOnChanges(changes: SimpleChanges): Promise<void> {
    if (changes['propuestaId'] && this.propuestaId > 0) {
      await this.loadAvances();
    }
  }

  // Cargar datos desde backend
  async loadAvances(): Promise<void> {
    if (!this.propuestaId) return;

    this.isLoading = true;
    this.errorMessage = '';

    try {
      const response = await this.propuestasAvancesService.get(
        [
          { key: 'propuesta_id', operator: '=', value: this.propuestaId },
          { key: 'deleted_at', operator: 'IS NULL', value: null }
        ],
        ['tipoAvance'], // Incluir relación
        { loader: false }
      );
      this.avances = response.data || [];
    } catch {
      this.errorMessage = 'Error al cargar los avances';
    } finally {
      this.isLoading = false;
    }
  }

  // Método público para que el padre lo llame
  public async refreshAvances(): Promise<void> {
    await this.loadAvances();
  }

  // ===== MÉTODOS PARA AVANCES =====

  /**
   * Método para editar un avance - emite evento al padre
   */
  editarAvance(avance: PropuestasAvancesModel): void {
    this.editRequest.emit(avance);
  }

  /**
   * Método para remover un avance con confirmación
   */
  async removerAvance(avance: PropuestasAvancesModel): Promise<void> {
    const dialogData: DialogData = {
      title: '¿Confirmar Eliminación?',
      body: `¿Está seguro que desea eliminar el avance del ${new Date(avance.fecha_avance).toLocaleDateString('es-ES')} con ${avance.porcentaje}% de progreso?Esta acción se puede deshacer.`,
      size: 'md',
      respYes: 'Sí, Eliminar',
      respNo: 'Cancelar',
      tipo: 'confirm'
    };

    try {
      // Esperar la respuesta del usuario
      const result = await new Promise<{ closedByAgree: boolean; closedByCancelled: boolean; closedByOutside: boolean }>((resolve) => {
        const subscription = this.dialogService.show(dialogData).subscribe((data) => {
          if (data !== null) {
            subscription.unsubscribe(); // Evitar memory leaks
            resolve(data);
          }
        });
      });

      if (result?.closedByAgree) {
        const updateResponse = await this.propuestasAvancesService.switch(avance.id);

        if (updateResponse) {
          // Mostrar diálogo de éxito
          const successDialog: DialogData = {
            title: '✅ Avance Eliminado',
            body: 'El avance ha sido eliminado exitosamente.',
            size: 'sm',
            respYes: 'OK',
            tipo: 'success'
          };

          // Esperar confirmación del diálogo de éxito
          await new Promise<{ closedByAgree: boolean; closedByCancelled: boolean; closedByOutside: boolean }>((resolve) => {
            const subscription = this.dialogService.show(successDialog).subscribe((data) => {
              if (data !== null) {
                subscription.unsubscribe();
                resolve(data);
              }
            });
          });

          // Recargar avances
          await this.refreshAvances();
        } else {
          const errorDialog: DialogData = {
            title: '❌ Error',
            body: 'No se pudo eliminar el avance. Por favor, intente nuevamente.',
            size: 'sm',
            respYes: 'Entendido',
            tipo: 'danger'
          };

          await new Promise<{ closedByAgree: boolean; closedByCancelled: boolean; closedByOutside: boolean }>((resolve) => {
            const subscription = this.dialogService.show(errorDialog).subscribe((data) => {
              if (data !== null) {
                subscription.unsubscribe();
                resolve(data);
              }
            });
          });
        }
      }
    } catch {
      const errorDialog: DialogData = {
        title: '❌ Error',
        body: 'No se pudo eliminar el avance. Por favor, intente nuevamente.',
        size: 'sm',
        respYes: 'Entendido',
        tipo: 'danger'
      };

      await new Promise<{ closedByAgree: boolean; closedByCancelled: boolean; closedByOutside: boolean }>((resolve) => {
        const subscription = this.dialogService.show(errorDialog).subscribe((data) => {
          if (data !== null) {
            subscription.unsubscribe();
            resolve(data);
          }
        });
      });
    }
  }
}
