import {Component, inject, OnInit} from '@angular/core';
import {CommonModule, DatePipe} from '@angular/common';
import {Router, RouterLink} from '@angular/router';
import {PropuestasModel} from "../../../models/propuestas.model";
import {PropuestasService} from "../../../controllers/propuestas.service";
import {LocalStorageService} from "../../../services/localStorage/local-storage.service";
import {FiltroPropuestasComponent, FiltroPropuestas} from "./filtro-propuestas-component/filtro-propuestas-component";

interface RowButton {
    key: string;
    text: string;
    title: string;
    style: {
        icon: string;
        text: string;
    };
}

@Component({
    selector: 'app-propuestas-list',
    imports: [
        CommonModule,
        DatePipe,
        RouterLink,
        FiltroPropuestasComponent
    ],
    templateUrl: './propuestas-list.html',
    styleUrl: './propuestas-list.css'
})
export class PropuestasList implements OnInit {
    propuestas: PropuestasModel[] = [];
    todasLasPropuestas: PropuestasModel[] = [];
    filtrosActivos: FiltroPropuestas = {};

    protected propuestasService = inject(PropuestasService);
    private router = inject(Router);
    private storage = inject(LocalStorageService);

    async ngOnInit(): Promise<void> {
        await this.getPropuestas();
    }

    async getPropuestas() {
        const currentUser = this.currentUser;
        if (!currentUser) {
            this.propuestas = [];
            this.todasLasPropuestas = [];
            return;
        }

        // Obtener todas las propuestas del usuario actual
        this.todasLasPropuestas = await this.propuestasService.all({
            conditionals: { user_id: currentUser.id },
            relations: ['tiempoActualUnidad', 'tiempoEsperadoUnidad']
        });

        // Aplicar filtros si hay alguno activo
        this.aplicarFiltros();
    }

    onFiltrarPropuestas(filtros: FiltroPropuestas): void {
        this.filtrosActivos = filtros;
        this.aplicarFiltros();
    }

    onLimpiarFiltros(): void {
        this.filtrosActivos = {};
        this.propuestas = [...this.todasLasPropuestas];
    }

    private aplicarFiltros(): void {
        let propuestasFiltradas = [...this.todasLasPropuestas];

        // Filtro por nombre (búsqueda parcial)
        if (this.filtrosActivos.nombre) {
            const searchTerm = this.filtrosActivos.nombre.toLowerCase().trim();
            propuestasFiltradas = propuestasFiltradas.filter(propuesta =>
                propuesta.nombre.toLowerCase().includes(searchTerm)
            );
        }

        // Filtro por tipo (exacto)
        if (this.filtrosActivos.tipo) {
            propuestasFiltradas = propuestasFiltradas.filter(propuesta =>
                propuesta.tipo === this.filtrosActivos.tipo
            );
        }

        // Filtro por rango de fecha de cumplimiento
        if (this.filtrosActivos.fechaCumplimientoInicio) {
            const fechaInicio = new Date(this.filtrosActivos.fechaCumplimientoInicio);
            propuestasFiltradas = propuestasFiltradas.filter(propuesta => {
                if (!propuesta.fecha_cumplimiento) return false;
                const fechaPropuesta = new Date(propuesta.fecha_cumplimiento);
                return fechaPropuesta >= fechaInicio;
            });
        }

        if (this.filtrosActivos.fechaCumplimientoFin) {
            const fechaFin = new Date(this.filtrosActivos.fechaCumplimientoFin);
            propuestasFiltradas = propuestasFiltradas.filter(propuesta => {
                if (!propuesta.fecha_cumplimiento) return false;
                const fechaPropuesta = new Date(propuesta.fecha_cumplimiento);
                return fechaPropuesta <= fechaFin;
            });
        }

        // Filtro por rango de fecha de creación
        if (this.filtrosActivos.fechaCreacionInicio) {
            const fechaInicio = new Date(this.filtrosActivos.fechaCreacionInicio);
            propuestasFiltradas = propuestasFiltradas.filter(propuesta => {
                if (!propuesta.created_at) return false;
                const fechaPropuesta = new Date(propuesta.created_at);
                return fechaPropuesta >= fechaInicio;
            });
        }

        if (this.filtrosActivos.fechaCreacionFin) {
            const fechaFin = new Date(this.filtrosActivos.fechaCreacionFin);
            propuestasFiltradas = propuestasFiltradas.filter(propuesta => {
                if (!propuesta.created_at) return false;
                const fechaPropuesta = new Date(propuesta.created_at);
                return fechaPropuesta <= fechaFin;
            });
        }

        this.propuestas = propuestasFiltradas;
    }

    get currentUser() {
        const userData = this.storage.getUser();
        return userData?.user ?? null;
    }

    get getRowButtons(): RowButton[] {
        return [
            {
                key: 'detalle',
                text: 'Ver Detalle',
                title: 'Ver Detalle',
                style: {
                    icon: 'bi bi-info',
                    text: 'text-xs',
                },
            },
        ];
    }

}
